import{_ as a,o as t,c as o,l as n,t as l,N as m}from"./chunks/framework.Gjrf2Eoj.js";const x=JSON.parse('{"title":"gitmailmap | x-cmd man (git man5) | Map author/committer names and/or E-Mail addresses","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitmailmap - Map author/committer names and/or E-Mail addresses","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitmailmap | x-cmd man (git man5) | Map author/committer names and/or E-Mail addresses"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitmailmap - Map author/committer names and/or E-Mail addresses"}]]},"headers":[],"params":{"isMan":true,"man":"gitmailmap","category":"git man5","desc":"Map author/committer names and/or E-Mail addresses"},"relativePath":"git/man5/gitmailmap.md","filePath":"git/man5/gitmailmap.md"}'),i={name:"git/man5/gitmailmap.md"},s={class:"visually-hidden"},r=m(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitmailmap - Map author/committer names and/or E-Mail addresses</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p>$GIT_WORK_TREE/.mailmap</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>If the file <strong>.mailmap</strong> exists at the toplevel of the repository, or at the location pointed to by the <strong>mailmap.file</strong> or <strong>mailmap.blob</strong> configuration options (see <strong>git-config</strong>(1)), it is used to map author and committer names and email addresses to canonical real names and email addresses.</p><h2 id="syntax" tabindex="-1">SYNTAX <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;SYNTAX&quot;">​</a></h2><p>The <em>#</em> character begins a comment to the end of line, blank lines are ignored.</p><p>In the simple form, each line in the file consists of the canonical real name of an author, whitespace, and an email address used in the commit (enclosed by <em>&lt;</em> and <em>&gt;</em>) to map to the name. For example:</p><blockquote><pre><code>Proper Name &lt;commit@email.xx&gt;
</code></pre></blockquote><p>The more complex forms are:</p><blockquote><pre><code>&lt;proper@email.xx&gt; &lt;commit@email.xx&gt;
</code></pre></blockquote><p>which allows mailmap to replace only the email part of a commit, and:</p><blockquote><pre><code>Proper Name &lt;proper@email.xx&gt; &lt;commit@email.xx&gt;
</code></pre></blockquote><p>which allows mailmap to replace both the name and the email of a commit matching the specified commit email address, and:</p><blockquote><pre><code>Proper Name &lt;proper@email.xx&gt; Commit Name &lt;commit@email.xx&gt;
</code></pre></blockquote><p>which allows mailmap to replace both the name and the email of a commit matching both the specified commit name and email address.</p><p>Both E-Mails and names are matched case-insensitively. For example this would also match the <em>Commit Name &lt;commit@email.xx&gt;</em> above:</p><blockquote><pre><code>Proper Name &lt;proper@email.xx&gt; CoMmIt NaMe &lt;CoMmIt@EmAiL.xX&gt;
</code></pre></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Git does not follow symbolic links when accessing a <strong>.mailmap</strong> file in the working tree. This keeps behavior consistent when the file is accessed from the index or a tree versus from the filesystem.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Your history contains commits by two authors, Jane and Joe, whose names appear in the repository under several forms:</p><blockquote><pre><code>Joe Developer &lt;joe@example.com&gt;
Joe R. Developer &lt;joe@example.com&gt;
Jane Doe &lt;jane@example.com&gt;
Jane Doe &lt;jane@laptop.(none)&gt;
Jane D. &lt;jane@desktop.(none)&gt;
</code></pre></blockquote><p>Now suppose that Joe wants his middle name initial used, and Jane prefers her family name fully spelled out. A <strong>.mailmap</strong> file to correct the names would look like:</p><blockquote><pre><code>Joe R. Developer &lt;joe@example.com&gt;
Jane Doe &lt;jane@example.com&gt;
Jane Doe &lt;jane@desktop.(none)&gt;
</code></pre></blockquote><p>Note that there&#39;s no need to map the name for <em>&lt;jane@laptop.(none)&gt;</em> to only correct the names. However, leaving the obviously broken <em>&lt;jane@laptop.(none)&gt;</em> and <em>&lt;jane@desktop.(none)&gt;</em> E-Mails as-is is usually not what you want. A <strong>.mailmap</strong> file which also corrects those is:</p><blockquote><pre><code>Joe R. Developer &lt;joe@example.com&gt;
Jane Doe &lt;jane@example.com&gt; &lt;jane@laptop.(none)&gt;
Jane Doe &lt;jane@example.com&gt; &lt;jane@desktop.(none)&gt;
</code></pre></blockquote><p>Finally, let&#39;s say that Joe and Jane shared an E-Mail address, but not a name, e.g. by having these two commits in the history generated by a bug reporting system. I.e. names appearing in history as:</p><blockquote><pre><code>Joe &lt;bugs@example.com&gt;
Jane &lt;bugs@example.com&gt;
</code></pre></blockquote><p>A full <strong>.mailmap</strong> file which also handles those cases (an addition of two lines to the above example) would be:</p><blockquote><pre><code>Joe R. Developer &lt;joe@example.com&gt;
Jane Doe &lt;jane@example.com&gt; &lt;jane@laptop.(none)&gt;
Jane Doe &lt;jane@example.com&gt; &lt;jane@desktop.(none)&gt;
Joe R. Developer &lt;joe@example.com&gt; Joe &lt;bugs@example.com&gt;
Jane Doe &lt;jane@example.com&gt; Jane &lt;bugs@example.com&gt;
</code></pre></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-check-mailmap</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,36);function p(e,c,d,h,g,u){return t(),o("div",null,[n("h1",s,l(e.$params.man),1),r])}const f=a(i,[["render",p]]);export{x as __pageData,f as default};
